// Parity harness: shared/params.json + shared/fixtures/*.json (generated by `python -m carelens.fixtures`).
// TS implementations are registered in src/core/parity.ts (IMPLEMENTATIONS). Fixtures without one are
// "pending" (listed in shared/fixtures/pending.json); the pending set may not grow. Not a medical device.
import { readFileSync, readdirSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { describe, expect, it } from 'vitest';
import { IMPLEMENTATIONS, compareOutputs, runParity, type Fixture } from '../../src/core/parity';

const SHARED = join(dirname(fileURLToPath(import.meta.url)), '..', '..', '..', 'shared');
const readJson = (p: string): any => JSON.parse(readFileSync(p, 'utf8'));

const params = readJson(join(SHARED, 'params.json'));

describe('shared/params.json', () => {
  it('has a positive integer version', () => {
    expect(Number.isInteger(params.version)).toBe(true);
    expect(params.version).toBeGreaterThanOrEqual(1);
  });

  it('has every required section', () => {
    for (const k of [
      'common', 'vitals', 'features', 'events', 'tracking', 'pipeline', 'scheduling', 'chest_shift',
      'contact_ppg', 'rppg', 'breathing_signal', 'tremor', 'audio',
    ]) {
      expect(params, `missing section ${k}`).toHaveProperty(k);
    }
    expect(Object.keys(params.vitals).sort()).toEqual(['breathing', 'heart_rate', 'pipeline_min_roi_px', 'roi', 'signal']);
    expect(Object.keys(params.events).sort()).toEqual(['fall', 'gait', 'inactivity', 'timeline']);
  });

  it('marks upcoming sections reserved with the planned values', () => {
    expect(params.contact_ppg.reserved).toBeUndefined(); // W1: live
    expect(params.rppg.reserved).toBeUndefined(); // W2: live
    expect(params.audio.reserved).toBeUndefined(); // W4: live
    for (const k of ['breathing_signal', 'tremor']) {
      expect(params[k].reserved).toBe(true);
    }
    expect([params.contact_ppg.band_lo_hz, params.contact_ppg.band_hi_hz]).toEqual([0.7, 3]);
    expect(params.rppg.methods).toEqual(['POS', 'CHROM']);
    expect([params.breathing_signal.band_lo_hz, params.breathing_signal.band_hi_hz]).toEqual([0.1, 0.7]);
    expect([params.tremor.band_lo_hz, params.tremor.band_hi_hz]).toEqual([3, 12]);
    expect(params.audio.labels).toEqual([
      'Cough', 'Snoring', 'Screaming', 'Crying, sobbing', 'Glass', 'Thump, thud',
    ]);
  });
});

// ---------------------------------------------------------------- fixture runner

const FIXTURE_DIR = join(SHARED, 'fixtures');
const fixtures: Fixture[] = readdirSync(FIXTURE_DIR)
  .filter((f) => f.endsWith('.json') && f !== 'pending.json')
  .sort()
  .map((f) => readJson(join(FIXTURE_DIR, f)));
const allowedPending: string[] = readJson(join(FIXTURE_DIR, 'pending.json')).pending;

describe('shared/fixtures', () => {
  it('are present and match the current params version', () => {
    expect(fixtures.length).toBeGreaterThan(0);
    for (const fx of fixtures) {
      expect(fx.params_version, fx.name).toBe(params.version);
      for (const k of ['name', 'description', 'input_level', 'input', 'expected', 'tolerance']) {
        expect(fx, `${fx.name}.${k}`).toHaveProperty(k);
      }
    }
  });

  it('every registered implementation passes; pending fixtures may not grow beyond pending.json', () => {
    const r = runParity(fixtures, IMPLEMENTATIONS, params, allowedPending);
    expect(r.failures).toEqual([]);
    expect(r.newlyPending, 'fixture lost its TS implementation or is unlisted in pending.json').toEqual([]);
    if (r.pending.length) console.info(`parity pending (${r.pending.length}): ${r.pending.join(', ')}`);
  });

  it('pending.json only names existing fixtures', () => {
    const names = fixtures.map((f) => f.name);
    for (const n of allowedPending) expect(names).toContain(n);
  });
});

describe('parity runner mechanics', () => {
  const fx = fixtures.find((f) => f.expected?.estimates?.length)!;

  it('compareOutputs: 1e-6 noise passes, flipped gate or value shift fails', () => {
    expect(compareOutputs(fx, fx.expected)).toEqual([]);
    const noisy = structuredClone(fx.expected);
    noisy.estimates.forEach((e: any) => { e.value += 1e-6; e.quality += 1e-6; });
    expect(compareOutputs(fx, noisy)).toEqual([]);
    const flipped = structuredClone(fx.expected);
    flipped.estimates[0].reported = !flipped.estimates[0].reported;
    expect(compareOutputs(fx, flipped).length).toBeGreaterThan(0);
    const shifted = structuredClone(fx.expected);
    shifted.estimates[0].value += 5;
    expect(compareOutputs(fx, shifted).length).toBeGreaterThan(0);
  });

  it('a registered implementation is actually executed and judged', () => {
    let calls = 0;
    const good = { [fx.name]: () => { calls++; return structuredClone(fx.expected); } };
    const r = runParity([fx], good, params, []);
    expect(calls).toBe(1);
    expect(r.executed).toEqual([fx.name]);
    expect(r.failures).toEqual([]);
    const bad = { [fx.name]: () => ({ estimates: [] }) };
    expect(runParity([fx], bad, params, []).failures.length).toBeGreaterThan(0);
  });

  it('a dropped implementation is caught as newly pending', () => {
    expect(runParity([fx], {}, params, [fx.name]).newlyPending).toEqual([]);
    expect(runParity([fx], {}, params, []).newlyPending).toEqual([fx.name]);
  });
});
